inputs = ['uj', 'agxc', 'kc', 'fyvb', 'jgbfba']
outputs = ['ufj', 'agxc', 'kc', 'fjbbvb', 'jgbfba']

print("Input/Output pairs:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' → '{out}'")

print("\nDetailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp != out:
        print(f"Pair {i}: '{inp}' vs '{out}'")
        # Find differences
        for j, (char_in, char_out) in enumerate(zip(inp, out)):
            if char_in != char_out:
                print(f"  Position {j}: '{char_in}' → '{char_out}'")
        if len(out) > len(inp):
            print(f"  Length increased from {len(inp)} to {len(out)}")
        elif len(out) < len(inp):
            print(f"  Length decreased from {len(inp)} to {len(out)}")

